import json

def unique_pairs(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("duplicate_key")
        result[key] = value
    return result

def validate(raw):
    if len(raw.encode("utf-8")) > 4096:
        raise ValueError("too_large")
    obj = json.loads(raw, object_pairs_hook=unique_pairs)
    if not isinstance(obj, dict) or set(obj) != {"quantity", "category"}:
        raise ValueError("unexpected_fields")
    if type(obj["quantity"]) is not int or not 1 <= obj["quantity"] <= 100:
        raise ValueError("invalid_quantity")
    if obj["category"] not in ("billing", "support", "other"):
        raise ValueError("invalid_category")
    return obj

assert validate('{"quantity":2,"category":"billing"}')["quantity"] == 2
bad_inputs = [
    '{"quantity":true,"category":"billing"}',
    '{"quantity":2,"category":"unknown"}',
    '{"quantity":2,"quantity":3,"category":"billing"}',
    '{"quantity":2,"category":"billing","execute":true}',
]
for raw in bad_inputs:
    try:
        validate(raw)
    except ValueError as error:
        print(str(error))
    else:
        raise AssertionError("invalid input accepted")

from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def subtotal(quantity, price):
    if type(quantity) is not int or not 1 <= quantity <= 10000:
        raise ValueError("quantity")
    try:
        unit = Decimal(price)
    except (InvalidOperation, TypeError):
        raise ValueError("price")
    if not unit.is_finite() or not Decimal("0") <= unit <= Decimal("1000000"):
        raise ValueError("price")
    return (unit * quantity).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

assert subtotal(3, "19.90") == Decimal("59.70")
assert subtotal(1, "1.005") == Decimal("1.01")
for bad in ("NaN", "Infinity", "-2"):
    try:
        subtotal(1, bad)
    except ValueError:
        pass
    else:
        raise AssertionError("bad amount")
print(subtotal(3, "19.90"))
print(subtotal(1, "1.005"))

import re

def tokens(text):
    return set(re.findall(r"\w+", text.casefold()))

def search(query, tenant, docs):
    query_terms = tokens(query)
    ranked = []
    for doc in docs:
        if doc["tenant"] != tenant or not doc["active"]:
            continue
        score = len(query_terms & tokens(doc["text"]))
        if score:
            ranked.append((score, doc["id"]))
    return [doc_id for _, doc_id in sorted(ranked, key=lambda x: (-x[0], x[1]))]

docs = [
    {"id": "a1", "tenant": "a", "active": True, "text": "payment invoice policy"},
    {"id": "b1", "tenant": "b", "active": True, "text": "payment invoice deadline"},
    {"id": "a0", "tenant": "a", "active": False, "text": "payment invoice deadline"},
]
assert search("invoice deadline", "a", docs) == ["a1"]
assert search("unknown", "a", docs) == []
print(search("invoice deadline", "a", docs))
print(search("unknown", "a", docs))

def check_claim(claim, sources):
    source_id, quote = claim["source_id"], claim["quote"]
    if source_id not in sources:
        return "unknown_source"
    if not quote or quote not in sources[source_id]:
        return "quote_not_found"
    return "quote_present_semantic_review_needed"

sources = {"p1": "Refund requests require operator review."}
good = {"source_id": "p1", "quote": "require operator review"}
bad = {"source_id": "p1", "quote": "always approved"}
assert check_claim(bad, sources) == "quote_not_found"
print(check_claim(good, sources))
print(check_claim(bad, sources))

def chunks(text, size=10, overlap=2):
    if type(size) is not int or type(overlap) is not int or not 0 <= overlap < size:
        raise ValueError("invalid_window")
    result = []
    start = 0
    while start < len(text):
        end = min(start + size, len(text))
        result.append({"id": f"doc-v1:{start}:{end}", "start": start, "end": end, "text": text[start:end]})
        if end == len(text):
            break
        start = end - overlap
    return result

result = chunks("abcdefghijklmnopqrstuv")
assert [c["start"] for c in result] == [0, 8, 16]
assert result[-1]["text"] == "qrstuv"
assert chunks("") == []
try:
    chunks("abc", 3, 3)
except ValueError:
    pass
else:
    raise AssertionError("infinite window accepted")
for chunk in result:
    print(chunk["id"], chunk["text"])

def metrics(actual, predicted):
    if len(actual) != len(predicted) or not actual:
        raise ValueError("dataset")
    tp = sum(a == "urgent" and p == "urgent" for a, p in zip(actual, predicted))
    fp = sum(a != "urgent" and p == "urgent" for a, p in zip(actual, predicted))
    fn = sum(a == "urgent" and p != "urgent" for a, p in zip(actual, predicted))
    return {"precision": tp / (tp + fp) if tp + fp else None,
            "recall": tp / (tp + fn) if tp + fn else None,
            "tp": tp, "fp": fp, "fn": fn}

result = metrics(["urgent", "urgent", "normal", "normal"],
                 ["urgent", "normal", "urgent", "normal"])
assert result["precision"] == 0.5 and result["recall"] == 0.5
assert metrics(["normal"], ["normal"])["recall"] is None
print(result)

import hashlib
import json
import sqlite3

conn = sqlite3.connect(":memory:")
conn.execute("CREATE TABLE drafts (tenant TEXT, key TEXT, digest TEXT, payload TEXT, PRIMARY KEY(tenant, key))")

def save(tenant, key, payload):
    raw = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
    digest = hashlib.sha256(raw.encode()).hexdigest()
    with conn:
        conn.execute("INSERT OR IGNORE INTO drafts VALUES (?, ?, ?, ?)", (tenant, key, digest, raw))
        stored_digest, stored_raw = conn.execute(
            "SELECT digest, payload FROM drafts WHERE tenant=? AND key=?", (tenant, key)
        ).fetchone()
        if stored_digest != digest:
            raise ValueError("idempotency_conflict")
    return json.loads(stored_raw)

assert save("a", "request-1", {"text": "draft"}) == {"text": "draft"}
assert save("a", "request-1", {"text": "draft"}) == {"text": "draft"}
assert conn.execute("SELECT COUNT(*) FROM drafts").fetchone()[0] == 1
try:
    save("a", "request-1", {"text": "changed"})
except ValueError as error:
    print(error)
else:
    raise AssertionError("conflict accepted")
print("stored_rows=", conn.execute("SELECT COUNT(*) FROM drafts").fetchone()[0], sep="")
conn.close()

import hashlib
import json

def fingerprint(payload):
    raw = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()

original = {"to": "demo@example.com", "body": "Draft", "revision": 1}
approval = {"digest": fingerprint(original), "approved_by": "operator-demo"}
changed = {**original, "body": "Changed", "revision": 2}
assert fingerprint(original) == approval["digest"]
assert fingerprint(changed) != approval["digest"]
print("original_matches=", fingerprint(original) == approval["digest"], sep="")
print("changed_matches=", fingerprint(changed) == approval["digest"], sep="")

from decimal import Decimal, ROUND_HALF_UP

def percent_change(current, previous):
    current, previous = Decimal(current), Decimal(previous)
    if not current.is_finite() or not previous.is_finite() or current < 0 or previous < 0:
        raise ValueError("nonnegative_finite_values_required")
    if previous == 0:
        return None
    return ((current - previous) * 100 / previous).quantize(Decimal("0.1"), rounding=ROUND_HALF_UP)

assert percent_change("120", "100") == Decimal("20.0")
assert percent_change("5", "0") is None
print(percent_change("120", "100"))
print(percent_change("5", "0"))
